-- LocalRadio 0.6 - local MP3s + multi-station injection (local + url tracks)
--
-- v0.2: game radio songs replaced by local MP3s from Audio (file:/// URIs).
-- v0.3: + custom stations injected at runtime.
-- v0.5: + tracks can be LOCAL (file=) or LINK (url=).
-- v0.6: + multiple custom stations from the GM panel (PANEL_STATIONS table).

-- ====== PANEL STATIONS (auto-generated by GM panel - edit in the panel) ======
local PANEL_STATIONS = {
}

-- ====== END PANEL STATIONS ======

-- Local MP3 files through the client's existing decoder; no HTTP service.
local previous=rawget(_G,'__localRadio')
if previous and previous.version==6 then return 'READY already installed' end
local sm,rm,config=rawget(_G,'gSoundMgr'),rawget(_G,'gRadioPlayerManager'),rawget(_G,'LTConfig')
local fileForId=rawget(_G,'__localRadioFile')
if not sm or type(sm.CreateSoundData)~='function' or type(sm.PlaySoundByData)~='function'
    or not rm or not config or not config.RadioSongsConfig or not config.VehicleRadioConfig
    or type(config.RadioSongsConfig.LoadAt)~='function' or type(config.VehicleRadioConfig.GetConfig)~='function'
    or type(rm.FilterUnlockedSongs)~='function' or type(rm.RefreshRadioChannel)~='function'
    or type(rm.PlayRadio)~='function' or type(fileForId)~='function' then
    return 'WAIT sound/radio/config managers or local file map not ready'
end
local count=tonumber(config.RadioSongsConfig.count) or 0
if count<=0 then return 'WAIT RadioSongsConfig is empty' end
local function log(text)local f=rawget(_G,'__localRadioLog');if f then f(tostring(text))end end
if previous then
    sm.CreateSoundData=previous.originalCreate
    sm.PlaySoundByData=previous.originalSound
    rm.FilterUnlockedSongs=previous.originalFilter
    rm.RefreshRadioChannel=previous.originalRefresh
    rm.PlayRadio=previous.originalPlay
    rm.GetRadioVoiceData=previous.originalVoices
end
local songs,byUrl={},{}
local mapped,missing=0,0
for i=0,count-1 do
    local r=config.RadioSongsConfig.LoadAt(i)
    if r then
        local id,uid=tonumber(r.Id),tonumber(r.OnlineUrlId) or 0
        if id and uid>0 then
            local uri=fileForId(uid)
            if type(uri)~='string' or uri:sub(1,8)~='file:///' then uri=nil end
            local entry={id=id,onlineId=uid,soundId=tonumber(r.SoundId) or 0,name=r.RadioSong,uri=uri}
            byUrl[uid]=entry
            if uri then songs[id]=entry;mapped=mapped+1 else missing=missing+1 end
        end
    end
end
local state={version=6,songs=songs,byUrl=byUrl,banks={},selected=0,logged={},localOnly=true}
local originalCreate,originalSound=sm.CreateSoundData,sm.PlaySoundByData
local originalFilter,originalRefresh,originalPlay=rm.FilterUnlockedSongs,rm.RefreshRadioChannel,rm.PlayRadio
local originalVoices=rm.GetRadioVoiceData
state.originalCreate=originalCreate;state.originalSound=originalSound
state.originalFilter=originalFilter;state.originalRefresh=originalRefresh;state.originalPlay=originalPlay;state.originalVoices=originalVoices
local kinds=LX6 and LX6.Audio and LX6.Audio.ExternalSourceType or {}
local urlIdType,urlType=kinds.Audio_Source_Mp3_UrlId or 1003,kinds.Audio_Source_Mp3_Url or 1002
sm.CreateSoundData=function(self,sid,pos,rotation,source,externalId,kind)
    local entry=kind==urlIdType and byUrl[tonumber(externalId)]
    if entry then
        if entry.uri then
            state.selected=state.selected+1
            log('LOCAL_FILE_SELECTED urlId='..tostring(entry.onlineId)..' uri='..entry.uri)
            return originalCreate(self,nil,pos,rotation,entry.uri,nil,urlType)
        end
        if entry.url then
            state.selected=state.selected+1
            log('LINK_SELECTED urlId='..tostring(entry.onlineId)..' url='..entry.url)
            return originalCreate(self,nil,pos,rotation,entry.url,nil,urlType)
        end
        log('LOCAL_MISSING urlId='..tostring(entry.onlineId))
        return nil
    end
    return originalCreate(self,sid,pos,rotation,source,externalId,kind)
end
sm.PlaySoundByData=function(self,data,post,start,finish,before,mark,cue)
    if data and type(data.externalSource)=='string' and data.externalType==urlType
        and (data.externalSource:sub(1,8)=='file:///' or data.externalSource:sub(1,8)=='https://' or data.externalSource:sub(1,7)=='http://') then
        return originalSound(self,data,function(uuid,sd)
            log('LOCAL_AUDIO_POST uuid='..tostring(uuid)..' uri='..tostring(data.externalSource))
            if post then return post(uuid,sd)end
        end,start,finish,before,mark,cue)
    end
    return originalSound(self,data,post,start,finish,before,mark,cue)
end
local function filtered(self,list)
    local unlocked=originalFilter(self,list)
    local result={};for _,id in ipairs(unlocked or {})do if songs[tonumber(id)] then result[#result+1]=id end end
    return result
end
local function filterStations(self)
    local result={}
    for _,id in ipairs(self.radioMapList or {})do
        local cfg=config.VehicleRadioConfig.GetConfig(id)
        if cfg and #filtered(self,cfg.SoundDataList)>0 then result[#result+1]=id end
    end
    for _,sid in ipairs(state.injectedIds or {}) do
        local present=false
        for _,id in ipairs(result) do if id==sid then present=true end end
        if not present then result[#result+1]=sid end
    end
    self.radioMapList=result;self.radioCount=#result;self.openCloudMusic=false
end
rm.FilterUnlockedSongs=filtered
rm.RefreshRadioChannel=function(self,...)
    local result=originalRefresh(self,...);filterStations(self);return result
end
rm.PlayRadio=function(self,...)
    filterStations(self)
    if self.radioCount<=0 then log('NO_LOCAL_STATIONS');return end
    return originalPlay(self,...)
end
if type(originalVoices)=='function' then rm.GetRadioVoiceData=function()end end
local ok,why=pcall(filterStations,rm)
if not ok then
    sm.CreateSoundData=originalCreate;sm.PlaySoundByData=originalSound
    rm.FilterUnlockedSongs=originalFilter;rm.RefreshRadioChannel=originalRefresh;rm.PlayRadio=originalPlay;rm.GetRadioVoiceData=originalVoices
    return 'WAIT initial station filtering: '..tostring(why)
end

-- ================= MULTI-STATION INJECTION (v0.6) =================
local stationsToInject={}
for _,st in ipairs(PANEL_STATIONS or {}) do
    stationsToInject[#stationsToInject+1]=st
end

local mySongsById,myStationsById={},{}
local injectedStations,injectedSongs=0,0
local okInj,errInj=pcall(function()
    local vrc=config.VehicleRadioConfig
    local rsc=config.RadioSongsConfig
    for _,st in ipairs(stationsToInject) do
        local songIds={}
        for _,t in ipairs(st.tracks or {}) do
            local songId=99000+90000+(tonumber(t.file) or 0)
            local uid=t.file
            local entry={id=songId,onlineId=uid,soundId=0,name=tostring(t.title or 'Track')}
            if t.url then
                entry.url=tostring(t.url)
            else
                local uri=fileForId(uid)
                if type(uri)~='string' or uri:sub(1,8)~='file:///' then
                    log('STATION file missing: station='..st.id..' fileId='..tostring(uid))
                    songId=nil
                else
                    entry.uri=uri
                end
            end
            if songId then
                mySongsById[songId]={Id=songId,RadioMark='0',RadioSong=tostring(t.title or 'Track'),
                    RadioSinger=tostring(t.singer or ''),SoundId=0,OnlineUrlId=uid,
                    MusicBPM=120,IsDefaultGain=true}
                songs[songId]=entry;byUrl[uid]=entry
                songIds[#songIds+1]=songId
                injectedSongs=injectedSongs+1
                log('STATION track: station='..st.id..' songId='..songId..' src='..(entry.uri or entry.url))
            end
        end
        if #songIds>0 then
            myStationsById[st.id]={Id=st.id,RadioName=st.name,RadioNumber=st.number,
                RadioCover=st.cover,RadioIcon=st.icon,
                SoundDataList=songIds,DJName=0}
            injectedStations=injectedStations+1
            log('STATION built: id='..st.id..' name='..st.name..' cover='..st.cover..' songs='..#songIds)
        end
    end
    if injectedStations>0 then
        local origVGet,origVLoad=vrc.GetConfig,vrc.LoadAt
        local origVCount=tonumber(vrc.count) or 0
        rawset(vrc,'GetConfig',function(id)
            local r=myStationsById[tonumber(id)]
            if r then return r end
            return origVGet(id)
        end)
        rawset(vrc,'count',origVCount+injectedStations)
        rawset(vrc,'LoadAt',function(i)
            local idx=tonumber(i)
            if idx and idx>=origVCount then
                local n=idx-origVCount+1
                local st=stationsToInject[n]
                if st then return myStationsById[st.id] end
            end
            return origVLoad(i)
        end)
        local origRGet=rsc.GetConfig
        rawset(rsc,'GetConfig',function(id)
            local r=mySongsById[tonumber(id)]
            if r then return r end
            return origRGet(id)
        end)
    end
end)
if okInj and injectedStations>0 then
    local ids={}
    for _,st in ipairs(stationsToInject) do
        if myStationsById[st.id] then ids[#ids+1]=st.id end
    end
    state.injectedIds=ids
    pcall(filterStations,rm)
    local map={}
    for _,id in ipairs(rm.radioMapList or {}) do map[#map+1]=tostring(id) end
    log('INJECTED stations='..injectedStations..' songs='..injectedSongs..' radioMapList='..table.concat(map,',')..' (radioCount='..tostring(rm.radioCount)..')')
    for _,st in ipairs(stationsToInject) do
        if myStationsById[st.id] then
            local chk=vrc.GetConfig(st.id)
            log('VERIFY id='..st.id..' -> '..tostring(chk and chk.RadioName)..' cover='..tostring(chk and chk.RadioCover)..' songs='..tostring(chk and chk.SoundDataList and #chk.SoundDataList))
        end
    end
elseif not okInj then
    log('INJECTION config hook failed: '..tostring(errInj))
end
-- ==============================================================

rawset(_G,'__localRadio',state)
log('READY localFiles='..tostring(mapped)..' unavailable='..tostring(missing)..' stations='..tostring(rm.radioCount))
return 'READY LocalRadio file mappings='..tostring(mapped)
